SELECT COUNT(*) AS "jumlah_tag" 
FROM "tags" 
WHERE "TagType" = 1 LIMIT 100;

SELECT COUNT(*) AS "audit_logs_today_count"
FROM "audit_logs"
WHERE "CreatedAt"::date = CURRENT_DATE LIMIT 100;

SELECT COUNT(*) AS "distinct_position_count"
FROM (
  SELECT DISTINCT "Position"
  FROM "participants"
  WHERE "Position" IS NOT NULL
) AS "t" LIMIT 100;

SELECT AVG(EXTRACT(EPOCH FROM (mcu_registrations."ScheduledDate" - mcu_registrations."RegistrationDate")) / 86400.0) AS "avg_gap_days" 
FROM "mcu_registrations" 
WHERE mcu_registrations."ScheduledDate" IS NOT NULL LIMIT 100;

SELECT COUNT(*) AS "vendor_or_contractor_count"
FROM "mcu_registrations" mr
WHERE mr."RegistrationType" IN ('VENDOR_CONTRACTOR','VENDOR') LIMIT 100;
